import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"Agents and sessions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md"}'),o={name:"guide/agents.md"};function i(d,e,r,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="agents-and-sessions" tabindex="-1">Agents and sessions <a class="header-anchor" href="#agents-and-sessions" aria-label="Permalink to &quot;Agents and sessions&quot;">​</a></h1><p>An <strong>agent</strong> owns a workspace, identity, model configuration, and channel connections. A <strong>session</strong> is one conversation&#39;s model context. Multiple agents can share one gateway while keeping their sessions separate.</p><h2 id="define-an-agent" tabindex="-1">Define an agent <a class="header-anchor" href="#define-an-agent" aria-label="Permalink to &quot;Define an agent&quot;">​</a></h2><p>Create an agent with <code>claude-gateway agents create</code>, then edit its source workspace files:</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>Required core instructions and capabilities</td></tr><tr><td><code>IDENTITY.md</code></td><td>Name, emoji, avatar, identity</td></tr><tr><td><code>SOUL.md</code></td><td>Tone and speaking style</td></tr><tr><td><code>USER.md</code></td><td>User preferences</td></tr><tr><td><code>MEMORY.md</code></td><td>Long-term core memory</td></tr><tr><td><code>HEARTBEAT.md</code></td><td>Proactive schedules</td></tr><tr><td><code>skills/</code></td><td>Agent-specific reusable skills</td></tr></tbody></table><p>For example, an <code>AGENTS.md</code> can begin:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are a personal research assistant.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Explain your findings clearly and link to the sources you used.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Before changing a file, read its existing content.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Report what you verified and what remains uncertain.</span></span></code></pre></div><p>The gateway assembles workspace files into <code>CLAUDE.md</code> on startup and file changes. Edit the source files, then ask the agent to describe its role to verify the update. Avoid editing the generated <code>CLAUDE.md</code>.</p><h2 id="manage-a-conversation" tabindex="-1">Manage a conversation <a class="header-anchor" href="#manage-a-conversation" aria-label="Permalink to &quot;Manage a conversation&quot;">​</a></h2><p>In a paired Telegram private chat, <code>/session</code> shows the current session, <code>/sessions</code> switches between sessions, and <code>/new &lt;name&gt;</code> starts a new one. <code>/compact</code> summarizes context. <code>/stop</code> interrupts the current turn. <code>/restart</code> restarts a session after confirmation.</p><p>Changing the agent&#39;s model affects all its sessions. Use <code>/models</code> and confirm the choice in a private chat. Chat history and the model&#39;s active context are separate: compacting context does not mean the persistent history database has been erased.</p><h2 id="tune-capacity" tabindex="-1">Tune capacity <a class="header-anchor" href="#tune-capacity" aria-label="Permalink to &quot;Tune capacity&quot;">​</a></h2><p><code>agents[].session.idleTimeoutMinutes</code> controls idle session eviction; <code>maxConcurrent</code> controls legacy concurrent sessions (the template uses 30 minutes and 20 sessions). These are different from worker task limits in <a href="./../preview/orchestration.html">unreleased orchestration</a>.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/main/README.md#workspace-files" target="_blank" rel="noreferrer">workspace files and session pool</a>.</p>`,14)])])}const m=t(o,[["render",i]]);export{g as __pageData,m as default};
